    /** weapons = bit (category - 130) for weapon item category id / 10000 % 100 + 100 (130 = 1H sword ... 149 = gun). */
    public record Entry(int id, int category, int weapons, int ammo, int minLevel) {
        public boolean allowsWeapon(int weaponItemId) {
            if (category != ACTIVE) {
                return true;
            }
            if (weaponItemId <= 0) {
                return false;
            }
            int code = weaponItemId / 10000 % 100 + 100 - 130;
            return code >= 0 && code < 32 && (weapons & (1 << code)) != 0;
        }
    }

